  [Serializable] sealed class Report {public bool passed;public string scope="Native 1080p bay building integration; bounded frame sampling, not whole-map or 4K proof.",resolution,gpu,playerSave,buildingSave;public List<string> checks=new List<string>(),failed=new List<string>(),errors=new List<string>(),warnings=new List<string>();public int starterCount,buildings,terrainVertices;public float normalFps,normalP95,planningFps,planningP95,travelDistance;}
  Report report;string evidence;
  void Check(bool pass,string text){report.checks.Add(text+": "+pass);if(!pass)report.failed.Add(text);}
  void LogReview(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(s);else if(type==LogType.Warning)report.warnings.Add(s);}
  IEnumerator Shot(string name){for(int i=0;i<6;i++)yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();var pixels=t.GetPixels32();int black=0,pink=0;foreach(var p in pixels){if(p.r+p.g+p.b<25)black++;if(p.r>245&&p.b>245&&p.g<10)pink++;}Check(black<pixels.Length*.8f,name+" visible frame");Check(pink<pixels.Length*.001f,name+" no shader fallback");File.WriteAllBytes(Path.Combine(evidence,name+".jpg"),t.EncodeToJPG(94));Destroy(t);}
  IEnumerator Perf(bool planning){for(int i=0;i<60;i++)yield return new WaitForEndOfFrame();var times=new List<float>();for(int i=0;i<480;i++){yield return new WaitForEndOfFrame();times.Add(Time.unscaledDeltaTime*1000);}times.Sort();if(planning){report.planningFps=1000/times.Average();report.planningP95=times[(int)(times.Count*.95)];}else{report.normalFps=1000/times.Average();report.normalP95=times[(int)(times.Count*.95)];}}
  Vector2Int FreeCell(int type){for(int z=-11;z<13;z++)for(int x=3;x<23;x++){var c=new Vector2Int(x,z);string r;if(CanPlace(c,type,1,true,out r))return c;}return new Vector2Int(999,999);}
  void ClearVisuals(){foreach(var b in buildings.Values){b.SetActive(false);Destroy(b);}buildings.Clear();Physics.SyncTransforms();}
  IEnumerator Review(){
   report=new Report();Application.logMessageReceived+=LogReview;StartCoroutine(DeadlineV28());var args=Environment.GetCommandLineArgs();int ix=Array.IndexOf(args,"-bay-v28-dir");evidence=ix>=0?args[ix+1]:"Verification/bay-v28-review01";Directory.CreateDirectory(evidence);game.AutoInput=true;game.DriveInput=Vector2.zero;
   report.playerSave=game.store.PathName;report.buildingSave=savePath;report.resolution=Screen.width+"x"+Screen.height;report.gpu=SystemInfo.graphicsDeviceName;report.starterCount=buildings.Count;
   yield return new WaitForSeconds(1);
   if(args.Contains("-bay-v28-native")){yield return NativeReview();yield break;}
   Check(Screen.width==1920&&Screen.height==1080,"native 1080p visible game window");Check(game.store.PathName.StartsWith(Application.temporaryCachePath)&&savePath.StartsWith(Application.temporaryCachePath),"both player and construction saves isolated before game load");
   Check(SeaHarborAndReefUpgradeV27.Active.Ready&&SeaWaterArtUpgradeV26.Active.Ready,"v27 harbor and v26.2 water remain active");
   var mat=waterFilter.GetComponent<Renderer>().sharedMaterial;Check(Mathf.Abs(mat.GetFloat("_CausticsIntensity")-.92f)<.00001f&&Mathf.Abs(mat.GetFloat("_GlintIntensity")-1.85f)<.00001f&&Mathf.Abs(mat.GetFloat("_GlintFocus")-72)<.00001f,"water optical defaults retained");
   report.terrainVertices=terrainRoot.GetComponentsInChildren<MeshFilter>().Sum(f=>f.sharedMesh.vertexCount);Check(waterFilter.sharedMesh.bounds.size.x>=299&&waterFilter.sharedMesh.bounds.size.z>=299,"water covers expanded navigation and zoomed planning camera");
   Check(DepthAt(new Vector3(11,0,4))>.6f&&DepthAt(new Vector3(11,0,4))<1.5f,"A warm sand terrace depth");Check(DepthAt(new Vector3(14,0,-16))>1.3f&&DepthAt(new Vector3(14,0,-16))<2.5f,"B south terrace depth");Check(DepthAt(new Vector3(16,0,24))>1.3f&&DepthAt(new Vector3(16,0,24))<2.5f,"B north terrace depth");Check(DepthAt(new Vector3(27,0,-1))<2.7f&&DepthAt(new Vector3(41,0,-1))>5.5f,"C crescent shelf preserves a deeper lagoon opening");
   Check(buildings.Count>=5&&data.placedBuildings.Any(b=>b.buildType==0)&&data.placedBuildings.Any(b=>b.buildType==2)&&data.placedBuildings.Any(b=>b.buildType==3),"starter layout has pier, coral garden and buoy");Check(cursorRoot.GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),"preview has no active physics colliders");
   Check(ValidBoatPosition(-10,-50)&&ValidBoatPosition(86,66)&&!ValidBoatPosition(float.NaN,0)&&!ValidBoatPosition(87,0),"expanded save bounds inclusive and nonfinite values rejected");
   game.PlaceBoat(new Vector3(60,SeaLifeRuntime.Sea,42),0);var start=game.boat.position;game.DriveInput=Vector2.up;yield return new WaitForSeconds(2);game.DriveInput=Vector2.zero;report.travelDistance=Vector3.Distance(start,game.boat.position);Check(report.travelDistance>1&&game.boat.position.x>34&&game.boat.position.z>32,"actual propulsion works beyond old X and Z limits");
   game.PlaceBoat(new Vector3(85.9f,SeaLifeRuntime.Sea,65.9f),45);game.DriveInput=Vector2.up;yield return new WaitForSeconds(1.2f);game.DriveInput=Vector2.zero;Check(game.body.position.x<=86.05f&&game.body.position.z<=66.05f,"new outer navigation limit enforced");game.SaveNow();var loaded=game.store.Load();Check(ValidBoatPosition(loaded.boatX,loaded.boatZ)&&loaded.boatX>34,"expanded boat coordinates survive save roundtrip ("+loaded.boatX+", "+loaded.boatZ+")");
   game.PlaceBoat(new Vector3(.8f,SeaLifeRuntime.Sea,5.2f),100);game.SnapWaterCamera();ToggleGodBuildMode(true);yield return new WaitForSeconds(.6f);Check(godBuildMode&&game.view.orthographic&&game.body.isKinematic,"planning owns camera and parks boat");Check(!oldHud.enabled&&gridRoot.gameObject.activeSelf,"planning hides conflicting gameplay HUD and shows grid");
   start=game.boat.position;game.DriveInput=Vector2.up;yield return new WaitForSeconds(.5f);game.DriveInput=Vector2.zero;Check(Vector3.Distance(start,game.boat.position)<.01f,"planning input does not propel boat");Check(!TryPlaceBuildingAt(new Vector2Int(999,999),0,0,true)&&!TryPlaceBuildingAt(new Vector2Int(0,0),-1,0,true),"invalid indices and out-of-bounds placement rejected");
   var cells=new Vector2Int[4];for(int type=0;type<4;type++){cells[type]=FreeCell(type);int before=data.placedBuildings.Count;Check(TryPlaceBuildingAt(cells[type],type,type,true)&&data.placedBuildings.Count==before+1,"construct type "+type+" through shared validation");int woodBefore=data.wood,stoneBefore=data.stone;Check(!TryPlaceBuildingAt(cells[type],type,0,true)&&data.wood==woodBefore&&data.stone==stoneBefore,"duplicate rejected without spending resources "+type);}
   int count=data.placedBuildings.Count;string snapshot=JsonUtility.ToJson(data);ClearVisuals();LoadLayout();yield return null;Check(buildings.Count==count&&JsonUtility.ToJson(data)==snapshot,"all structures, rotations and resources reload consistently");
   for(int type=0;type<4;type++){int countBefore=buildings.Count;Check(TryRemoveBuildingAt(cells[type],true)&&buildings.Count==countBefore-1,"dismantle and refund type "+type);}
   // Test a deliberate empty layout using a separate file, then restore the real test layout.
   string layoutPath=savePath,layoutJson=JsonUtility.ToJson(data);ClearVisuals();savePath=Path.Combine(Application.temporaryCachePath,"bay-v28-empty-"+TestId+".json");data=new BayExpansionSaveData();SaveLayout();LoadLayout();Check(buildings.Count==0&&data.placedBuildings.Count==0,"empty saved bay does not regenerate starter buildings");savePath=layoutPath;data=JsonUtility.FromJson<BayExpansionSaveData>(layoutJson);LoadLayout();
   var candidate=FreeCell(0);int oldWood=data.wood;data.wood=0;Check(!TryPlaceBuildingAt(candidate,0,0,true),"insufficient materials prevent building");data.wood=oldWood;
   ToggleGodBuildMode(false);Check(!game.view.orthographic&&!game.body.isKinematic&&oldHud.enabled,"leaving planning restores gameplay projection, movement and HUD");
   game.PlaceBoat(game.dockBerth,90);game.ToggleBoard();Check(game.OnFoot,"existing landing remains accessible");yield return WalkTo(CellPosition(new Vector2Int(0,0)));yield return WalkTo(CellPosition(new Vector2Int(1,0)));game.PlaceWalker(game.Grounded(game.dockFeet));game.ToggleBoard();Check(!game.OnFoot,"existing boarding remains accessible");
   game.NoticeTime=0;game.ui.Refresh();game.enabled=false;CameraAt(new Vector3(15,0,2),24,45,-20);yield return Shot("preview");yield return Perf(false);
   ToggleGodBuildMode(true);focus=new Vector3(19,SeaLifeRuntime.Sea,2);godOrthoSize=30;yield return new WaitForSeconds(1);yield return Shot("02-god-build-grid");yield return Perf(true);
   focus=new Vector3(35,SeaLifeRuntime.Sea,-2);godOrthoSize=18;yield return new WaitForSeconds(.7f);yield return Shot("03-crescent-atoll");ToggleGodBuildMode(false);CameraAt(new Vector3(3,SeaLifeRuntime.Sea,2.4f),9,46,-28);yield return Shot("04-pier-extension");
   report.buildings=buildings.Count;Check(bayLights.Count(l=>l!=null&&l.enabled)<=4,"additional lamp lights have a four-light budget");game.SaveNow();FinishReview();
  }
  IEnumerator WalkTo(Vector3 point){float until=Time.unscaledTime+5;while(Time.unscaledTime<until){var d=point-game.walker.position;d.y=0;if(d.magnitude<.35f)break;var local=Quaternion.Euler(0,18,0)*d.normalized;game.DriveInput=new Vector2(local.x,local.z);yield return null;}game.DriveInput=Vector2.zero;var delta=point-game.walker.position;delta.y=0;Check(delta.magnitude<.5f&&game.walker.position.y>.35f,"actual walker reaches extension "+point.x+", "+point.z+" at "+game.walker.position);}
  void CameraAt(Vector3 p,float size,float pitch,float yaw){var q=Quaternion.Euler(pitch,yaw,0);game.view.orthographic=false;game.view.fieldOfView=2*Mathf.Atan(size/104)*Mathf.Rad2Deg;game.view.transform.SetPositionAndRotation(p-q*Vector3.forward*104,q);}
  void FinishReview(){report.passed=report.failed.Count==0&&report.errors.Count==0;File.WriteAllText(Path.Combine(evidence,"result.json"),JsonUtility.ToJson(report,true));Application.logMessageReceived-=LogReview;Debug.Log("BAY_V28_REVIEW_DONE "+report.passed);Application.Quit(report.passed?0:2);}
  IEnumerator DeadlineV28(){yield return new WaitForSecondsRealtime(240);if(report!=null){report.failed.Add("review timeout");FinishReview();}}
  void Phase(string s){File.WriteAllText(Path.Combine(evidence,"native-state.json"),"{\"phase\":\""+s+"\"}");}
  IEnumerator NativeReview(){
   game.AutoInput=false;game.PlaceBoat(new Vector3(.8f,SeaLifeRuntime.Sea,5.2f),100);game.NoticeTime=0;game.SnapWaterCamera();var start=game.boat.position;
   Phase("await-enter");float deadline=Time.unscaledTime+35;while(!godBuildMode&&Time.unscaledTime<deadline)yield return null;Check(godBuildMode,"Windows G enters planning");yield return new WaitForSeconds(.6f);
   var cam=focus;Phase("await-pan");deadline=Time.unscaledTime+20;while(Vector3.Distance(cam,focus)<1&&Time.unscaledTime<deadline)yield return null;Check(Vector3.Distance(cam,focus)>1,"Windows W pans planning camera");Check(Vector3.Distance(start,game.boat.position)<.03f,"Windows WASD does not drive boat in planning");
   Phase("await-select");deadline=Time.unscaledTime+20;while(selected!=2&&Time.unscaledTime<deadline)yield return null;Check(selected==2,"Windows 3 selects coral without changing boat tool");Phase("await-rotate");int oldRotation=rotation;deadline=Time.unscaledTime+20;while(rotation==oldRotation&&Time.unscaledTime<deadline)yield return null;Check(rotation!=oldRotation,"Windows R rotates construction preview");
   // Supply a validated cell for native mouse placement, preserving the exact UI/input path.
   var nativeCell=FreeCell(2);focus=CellPosition(nativeCell);godOrthoSize=16;yield return new WaitForSeconds(.7f);Vector3 screen=game.view.WorldToScreenPoint(CellPosition(nativeCell));File.WriteAllText(Path.Combine(evidence,"mouse-target.json"),"{\"x\":"+screen.x.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"y\":"+screen.y.ToString(System.Globalization.CultureInfo.InvariantCulture)+"}");int before=buildings.Count;
   Phase("await-place");deadline=Time.unscaledTime+25;while(buildings.Count==before&&Time.unscaledTime<deadline)yield return null;Check(buildings.Count==before+1,"native left click constructs on selected cell");yield return Shot("native-placed");Phase("await-remove");deadline=Time.unscaledTime+25;while(buildings.Count!=before&&Time.unscaledTime<deadline)yield return null;Check(buildings.Count==before,"native right click dismantles and refunds");Phase("await-exit");deadline=Time.unscaledTime+20;while(godBuildMode&&Time.unscaledTime<deadline)yield return null;Check(!godBuildMode&&!game.body.isKinematic&&!game.view.orthographic,"Windows G restores navigation camera and control");yield return Shot("native-return");Phase("done");FinishReview();
  }
